param(
  [string]$ProjectRoot = "D:\simras-digital-twin-repository\simras-digital-twin"
)

$ErrorActionPreference = "Stop"
Set-Location $ProjectRoot
[Environment]::CurrentDirectory = (Get-Location).Path

$stamp = Get-Date -Format "yyyyMMdd_HHmmss"
$backup = Join-Path $ProjectRoot "archive\inspections_real_page_$stamp"
New-Item -ItemType Directory -Force $backup | Out-Null

$front = ".\frontend\src\pages\infrastructure\InspectionsPage.tsx"
$compat = ".\backend\app\api\routes\ui_compat.py"

foreach ($file in @($front,$compat)) {
  if (Test-Path $file) {
    Copy-Item $file (Join-Path $backup (Split-Path $file -Leaf)) -Force
  }
}

Write-Host "`n============================================================" -ForegroundColor Cyan
Write-Host "SIMRAS REAL INSPECTIONS PAGE" -ForegroundColor Cyan
Write-Host "============================================================" -ForegroundColor Cyan
Write-Host "Backup: $backup" -ForegroundColor DarkGray

Write-Host "`n=== 1. PATCH INSPECTIONS READ API ===" -ForegroundColor Cyan

@'
from pathlib import Path
import re

p = Path("backend/app/api/routes/ui_compat.py")

if not p.exists():
    print("ui_compat.py not found; no backend compatibility patch applied.")
    raise SystemExit(0)

text = p.read_text(encoding="utf-8-sig")

pattern = re.compile(
    r'@router\.get\("/inspections"\)\s*'
    r'async def inspections\(.*?'
    r'(?=\n\n@router\.get\("/maintenance"\))',
    re.DOTALL,
)

replacement = """@router.get("/inspections")
async def inspections(
    limit: int = Query(100, ge=1, le=1000),
    session: AsyncSession = Depends(get_db),
):
    rows = (
        await session.execute(
            select(
                Inspection,
                Asset.asset_code,
                Asset.name,
            )
            .join(
                Asset,
                Asset.id == Inspection.asset_id,
            )
            .order_by(
                desc(Inspection.inspection_date)
            )
            .limit(limit)
        )
    ).all()

    items = []

    for row, asset_code, asset_name in rows:
        score = _value(
            row,
            "score",
            "condition_score",
            "inspection_score",
        )

        items.append(
            {
                "id": row.id,
                "asset_code": asset_code,
                "asset_id": asset_code,
                "asset_name": asset_name,
                "inspection_type": _value(
                    row,
                    "inspection_type",
                    default="Inspection",
                ),
                "inspection_date": _iso(
                    _value(row, "inspection_date")
                ),
                "inspector": _value(
                    row,
                    "inspector",
                    "inspector_name",
                ),
                "inspection_score": score,
                "condition_score": score,
                "condition": _value(row, "condition"),
                "notes": _value(
                    row,
                    "findings",
                    "notes",
                    "remarks",
                ),
                "quality_flag": _value(
                    row,
                    "quality_flag",
                ),
                "is_synthetic": bool(
                    _value(
                        row,
                        "is_synthetic",
                        default=False,
                    )
                ),
                "source_id": _value(
                    row,
                    "source_id",
                ),
                "created_at": _iso(
                    _value(
                        row,
                        "created_at",
                        "inspection_date",
                    )
                ),
            }
        )

    return {
        "total": len(items),
        "items": items,
    }
"""

new_text, count = pattern.subn(replacement, text, count=1)

if count:
    p.write_text(new_text, encoding="utf-8")
    print("Global /inspections endpoint upgraded.")
else:
    print("Existing global /inspections pattern not found; no destructive edit made.")
'@ | py -

if ($LASTEXITCODE -ne 0) {
  throw "BACKEND INSPECTION API PATCH FAILED"
}

Write-Host "`n=== 2. INSTALL REAL INSPECTIONS UI ===" -ForegroundColor Cyan

[IO.File]::WriteAllBytes(
  $front,
  [Convert]::FromBase64String("")
)

Write-Host "InspectionsPage.tsx installed." -ForegroundColor Green

Write-Host "`n=== 3. COMPILE + BUILD BEFORE SWITCH ===" -ForegroundColor Cyan

py -m py_compile ".\backend\app\main.py"

if (Test-Path $compat) {
  py -m py_compile $compat
}

if ($LASTEXITCODE -ne 0) {
  throw "BACKEND COMPILE FAILED - RUNNING STACK NOT REPLACED"
}

Push-Location ".\frontend"
npm run build
$frontExit = $LASTEXITCODE
Pop-Location

if ($frontExit -ne 0) {
  throw "FRONTEND BUILD FAILED - RUNNING STACK NOT REPLACED"
}

Write-Host "FRONTEND BUILD PASS" -ForegroundColor Green

Write-Host "`n=== 4. BUILD IMAGES + PREFLIGHT ===" -ForegroundColor Cyan

docker compose build backend frontend

if ($LASTEXITCODE -ne 0) {
  throw "DOCKER BUILD FAILED - RUNNING STACK NOT REPLACED"
}

docker compose run --rm --no-deps backend python -c "from app.main import app; p={getattr(r,'path','') for r in app.routes}; req=['/api/v1/inspections','/api/v1/assets/{asset_code}/inspections']; m=[x for x in req if x not in p]; print('ROUTE_PREFLIGHT=', 'PASS' if not m else 'FAIL'); print('MISSING=',m); raise SystemExit(1 if m else 0)"

if ($LASTEXITCODE -ne 0) {
  throw "INSPECTION ROUTE PREFLIGHT FAILED - RUNNING STACK NOT REPLACED"
}

Write-Host "`n=== 5. START UPDATED BACKEND + FRONTEND ===" -ForegroundColor Cyan

docker compose up -d --force-recreate backend frontend
Start-Sleep -Seconds 8

Write-Host "`n=== 6. LIVE INSPECTION DATA ===" -ForegroundColor Cyan

$inspectCode = curl.exe -s -o "$env:TEMP\simras_inspections.json" -w "%{http_code}" `
  "http://localhost:8000/api/v1/inspections?limit=1000"

Write-Host "Inspections API : $inspectCode"

if ($inspectCode -eq "200") {
  Get-Content "$env:TEMP\simras_inspections.json" -Raw |
    py -c "import sys,json; d=json.load(sys.stdin); x=d.get('items',d if isinstance(d,list) else []); syn=sum(1 for i in x if i.get('is_synthetic') is True or 'SYNTHETIC' in str(i.get('quality_flag','')).upper() or 'DEMONSTRATION' in str(i.get('quality_flag','')).upper()); print('TOTAL DB INSPECTIONS =',len(x)); print('SYNTHETIC/DEMO =',syn); print('REAL/APPROVED =',len(x)-syn); [print((i.get('asset_code') or i.get('asset_id')),'|',i.get('inspection_date'),'|',i.get('inspection_type'),'|',i.get('condition'),'|',i.get('quality_flag'),'| synthetic=',i.get('is_synthetic')) for i in x[:5]]"
}

Write-Host "`n=== 7. DATABASE CHECK ===" -ForegroundColor Cyan

$dbUser = (docker compose exec -T db printenv POSTGRES_USER).Trim()
$dbName = (docker compose exec -T db printenv POSTGRES_DB).Trim()

docker compose exec -T db psql `
  -U $dbUser `
  -d $dbName `
  -P pager=off `
  -c "SELECT COUNT(*) AS total_inspections, COUNT(*) FILTER (WHERE COALESCE(is_synthetic,FALSE)=FALSE) AS real_inspections, COUNT(*) FILTER (WHERE COALESCE(is_synthetic,FALSE)=TRUE) AS synthetic_inspections FROM inspections;"

Write-Host "`n=== 8. WRITE SECURITY CONTRACT ===" -ForegroundColor Cyan

Write-Host "POST /api/v1/inspections uses X-Admin-API-Key" -ForegroundColor Green

Write-Host "`n=== 9. FRONTEND CHECK ===" -ForegroundColor Cyan

$pageCode = curl.exe -s -o NUL -w "%{http_code}" `
  "http://localhost:5173/infrastructure/inspections"

Write-Host "Inspection page : $pageCode"
docker compose ps

if ($pageCode -eq "200" -and $inspectCode -eq "200") {
  Write-Host "`n============================================================" -ForegroundColor Green
  Write-Host "REAL INSPECTIONS PAGE CONNECTED" -ForegroundColor Green
  Write-Host "============================================================" -ForegroundColor Green
  Write-Host "Synthetic/demo rows are hidden from operational UI."
  Write-Host "Approved writes are stored non-synthetic by the backend."
  Write-Host "Database volume was not recreated."
  Write-Host "Backup: $backup"
}

Start-Process "http://localhost:5173/infrastructure/inspections"
